package net.officefloor.hq.app.claim;

/**
 * A claim's status: it starts DRAFT, is opened (OPEN) and then settled (SETTLED); a clerk settling one above the
 * clerk limit leaves it PENDING, which a steward approves (SETTLED) or rejects (back to OPEN). A DRAFT, OPEN or
 * PENDING claim can be voided (VOID), and a steward may void a SETTLED one within 7 days of its settlement. VOID is final. Only OPEN, PENDING and SETTLED claims count toward
 * totals.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** The status an action ("open", "settle", "approve", "reject", "void") moves this one to, or null when it is not
     *  allowed. A settle above the clerk limit by a clerk ends in PENDING instead. */
    public ClaimStatus after(String action) {
        return switch (action) {
            case "open" -> this == DRAFT ? OPEN : null;
            case "settle" -> this == OPEN ? SETTLED : null;
            case "approve" -> this == PENDING ? SETTLED : null;
            case "reject" -> this == PENDING ? OPEN : null;
            case "void" -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED ? VOID : null;
            default -> null;
        };
    }

    /** Whether a claim in this status is open: OPEN or PENDING (it goes overdue, and a hold takes it out of the
     *  totals). */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }

    /** The audit event recorded on entering this status. */
    public String event() {
        return switch (this) {
            case OPEN -> "CLAIM_OPENED";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> "CLAIM_DRAFTED";
        };
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;

/** The claim form's rules, shared by the steps that add claims one at a time and many at once. */
public final class ClaimRules {

    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");

    private static final Pattern NUMBER = Pattern.compile("(.+-)?\\d{1,9}");

    private ClaimRules() {
    }

    /** Checks one claim form's fields, with no tags, as ValidateClaim does; a null field is blank. */
    public static ClaimInput check(String amountField, String dateField, String noteField, String correctsField,
            String refField) throws InvalidClaimException {
        return check(amountField, dateField, noteField, correctsField, refField, null);
    }

    /** Checks one claim form's fields as ValidateClaim does; a null field is blank. */
    public static ClaimInput check(String amountField, String dateField, String noteField, String correctsField,
            String refField, String tagsField) throws InvalidClaimException {
        String amount = amountField == null ? "" : amountField.trim();
        String date = dateField == null ? "" : dateField.trim();
        String note = noteField == null ? "" : noteField.trim();
        String corrects = correctsField == null ? "" : correctsField.trim();
        String ref = refField == null ? "" : refField.trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("The amount must be a number with up to two decimals.");
        }
        if (!corrects.isEmpty() && !NUMBER.matcher(corrects).matches()) {
            throw new InvalidClaimException("Corrects must be a claim number.");
        }
        BigDecimal value = new BigDecimal(amount).setScale(2);
        if (value.signum() < 0 && corrects.isEmpty()) {
            throw new InvalidClaimException("A negative amount is a correction: name the settled claim it corrects.");
        }
        if (value.signum() >= 0 && !corrects.isEmpty()) {
            throw new InvalidClaimException("Only a correction (a negative amount) corrects a claim.");
        }
        LocalDate parsed = null;
        if (!date.isEmpty()) {
            try {
                parsed = LocalDate.parse(date);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimException("Not a date: " + date);
            }
        }
        return new ClaimInput(value, parsed, note, corrects.isEmpty() ? null : corrects,
                ref.isEmpty() ? null : ref, Tags.normalise(tagsField));
    }

    /** The claim the input makes for the person, not yet saved; refused as BuildClaim refuses it. Its due-by is the
     *  terms-th business day after its date, skipping weekends and the sheet's holidays now on its list. */
    public static Claim make(ClaimInput input, Sheet sheet, Person person, ClaimRepository repository,
            PeriodRepository periods, PersonGradeRepository grades, HolidayRepository holidays) throws InvalidClaimException {
        LocalDate date = input.date() != null ? input.date() : sheet.entryDateInForce();
        int terms = sheet.termsFor(person.getTerms(), grades.gradesOf(person).on(date), date);
        LocalDate dueBy = holidays.dueBy(sheet.getId(), date, terms);
        if (periods.isClosedOn(sheet.getId(), dueBy)) {
            throw new InvalidClaimException("No claim can be added in a closed period.");
        }
        if (person.retiredOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date.");
        }
        LocalDate correctsDate = repository.checkCorrects(sheet.getId(), person.getId(), input.corrects());
        repository.checkRef(sheet.getId(), null, input.ref());
        Claim claim = new Claim(sheet.getId(), person.getId(), input.amount(), date, input.note(), input.corrects());
        claim.setCorrectsDate(correctsDate);
        claim.setRef(input.ref());
        claim.setTags(input.tags());
        claim.setLateEntry(periods.isSoftClosedOn(sheet.getId(), dueBy));
        claim.fixDue(date, terms, holidays.datesOf(sheet.getId()));
        return claim;
    }

    /** Records the claim's adding (its ref, then its tags, at the end, when it has them), and after it, when it is a late entry, its LATE_ENTRY. */
    public static void auditAdded(Claim claim, String personName, String by, Audit audit) {
        audit.record(ClaimAudit.line("CLAIM_ADDED", claim, personName, by)
                + (claim.getRef() == null ? "" : " ref=" + claim.getRef())
                + (claim.getTags() == null ? "" : " tags=" + claim.getTags()));
        if (claim.isLateEntry()) {
            audit.record(ClaimAudit.line("LATE_ENTRY", claim, personName, by));
        }
    }

    /** Writes the claim's status log entry as LogClaimStatus does, made by the given user. */
    public static void log(Claim claim, Sheet sheet, ClaimLogRepository log, PersonRepository people,
            RateRepository rates, PersonGradeRepository grades, String by) {
        BigDecimal due = people.findById(claim.getPersonId())
                .map(p -> new ClaimFigures(rates.findInChain(claim.getSheetId()),
                        grades.gradesOf(p), sheet).due(claim))
                .orElse(null);
        log.saveAndFlush(new ClaimLog(claim, by, sheet.getToday(), due));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Saves the claim's changes; refuses them unless the claim is a DRAFT (an open claim is voided and added anew
 * instead), when its due-by (as it stands before the edit) is in a closed period, when its date moves to one whose due-by
 * (its person's terms on that date, counted in business days) would be in a closed period, and when it would move after its
 * person's retirement date, a correction that does not name a settled claim of its person, and a reference another claim on the sheet has. Saving records who
 * last edited it and closes the claim's editor: it releases the claim's lock. Its due-by keeps counting from the date and
 * terms fixed when it was created ({@link Claim#getDueFrom}). */
public class ApplyClaim {
    public void apply(@Val ClaimInput input, @Val Sheet sheet, @Val Claim claim, ClaimRepository repository,
            PeriodRepository periods, PersonRepository people, PersonGradeRepository grades, HolidayRepository holidays,
            @RequestHeader(name = "X-User", required = false) String userHeader) throws InvalidClaimException {
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new InvalidClaimException("Only a draft claim can be edited; void it and add a new one.");
        }
        LocalDate date = input.date() != null ? input.date() : sheet.getToday();
        if (periods.isClosedOn(sheet.getId(), claim.getDueBy())) {
            throw new InvalidClaimException("No claim can be edited in a closed period.");
        }
        Person person = people.findById(claim.getPersonId()).orElse(null);
        if (person != null && !date.equals(claim.getDate())) {
            int terms = sheet.termsFor(person.getTerms(), grades.gradesOf(person).on(date), date);
            if (periods.isClosedOn(sheet.getId(), holidays.dueBy(sheet.getId(), date, terms))) {
                throw new InvalidClaimException("No claim can be moved to a date whose due-by is in a closed period.");
            }
        }
        if (person != null && person.retiredOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date.");
        }
        LocalDate correctsDate = repository.checkCorrects(sheet.getId(), claim.getPersonId(), input.corrects());
        repository.checkRef(sheet.getId(), claim.getId(), input.ref());
        claim.setAmount(input.amount());
        claim.setCorrects(input.corrects());
        claim.setCorrectsDate(correctsDate);
        claim.setDate(date);
        claim.setNote(input.note());
        claim.setRef(input.ref());
        claim.setTags(input.tags());
        claim.setLockedBy(null);
        claim.setEditedBy(AuditUser.decode(userHeader));
        repository.saveAndFlush(claim);
    }
}

